-- Bulk-imports 482 real off-plan/ready projects, scraped from 217 Dubai
-- developers' own websites (background research agents, one pass per
-- developer, WebFetch against each site's homepage and likely
-- /projects//properties/etc paths -- see conversation for the full method).
--
-- Deliberately conservative: of ~914 individual project mentions found,
-- only these 482 made it in. The rest were dropped rather than guessed --
-- ~156 had no location stated at all, ~91 were explicitly outside Dubai
-- (other emirates or other countries entirely, since developers often list
-- their full portfolio), and ~185 had a location that couldn't be matched
-- to one of this platform's 159 real community records with confidence
-- (generic "Dubai" alone was also excluded, not fuzzy-matched, after an
-- early version of the matching script produced false positives like a
-- bare "Dubai" resolving to "Dubai Land Residence Complex" purely because
-- both strings contain the word "Dubai").
--
-- Every row lands as status = 'draft' with approval_status defaulting to
-- 'pending' -- nothing here is visible on the public site until an admin
-- reviews and explicitly publishes it. Pricing/bedrooms/handover fields
-- use the column's real default (0 / null) whenever the source site didn't
-- state them, never a guessed number. developer_id is resolved by exact
-- name match against the existing developers table (all 217 already
-- imported via patch_90), so this migration must run after that one.
insert into projects (developer_id, community_id, slug, name, property_type, price_from_aed, bedrooms_from, bedrooms_to, handover_quarter, handover_year, status)
select v.developer_id, v.community_id, v.slug, v.name, v.property_type, v.price_from_aed, v.bedrooms_from, v.bedrooms_to, v.handover_quarter, v.handover_year, 'draft'
from (values
((select id from developers where name = 'AA & HMB Real Estate Development'), 'eb65fca4-f335-4f0e-870a-2a593c384e43'::uuid, 'beverly-gardens-aa-hmb-real-', 'Beverly Gardens', 'Residential', 0, 0, 0, null, null),
